create table if not exists equipment(id bigint auto_increment primary key,asset_code varchar(50) not null unique,name varchar(100) not null,category varchar(60) not null,lab_room varchar(60) not null,status varchar(30) not null);
create table if not exists reservation(id bigint auto_increment primary key,equipment_id bigint not null,student_id bigint not null,start_at timestamp not null,end_at timestamp not null,purpose varchar(300) not null,status varchar(30) not null,review_note varchar(300),created_at timestamp not null);
create table if not exists repair_order(id bigint auto_increment primary key,equipment_id bigint not null,reporter_id bigint not null,description varchar(500) not null,status varchar(30) not null,resolution varchar(500),created_at timestamp not null,resolved_at timestamp);
